from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel
from typing import Optional
from kafka import KafkaProducer

router = APIRouter()

class PublishRequest(BaseModel):
    topic: str
    key: Optional[str] = None
    value: str

class ConsumeRequest(BaseModel):
    topic: str

class PublishResponse(BaseModel):
    topic: str
    partition: int
    offset: int

class ConsumeResponse(BaseModel):
    value: str
    key: str
    topic: str
    partition: int
    offset: int

@router.post("/kafka/publish")
def publish_message(
    publish_request: PublishRequest, 
    producer: KafkaProducer = Depends(get_producer)
):
    producer.send(publish_request.topic, key=publish_request.key, value=publish_request.value)
    return PublishResponse(topic=publish_request.topic, partition=producer.partitions[publish_request.topic][0], offset=producer.offsets[publish_request.topic][0])

@router.get("/kafka/consume")
def consume_message(
    consume_request: ConsumeRequest, 
    producer: KafkaProducer = Depends(get_producer)
):
    for message in producer.get_messages(consume_request.topic):
        return ConsumeResponse(value=message.value, key=message.key, topic=message.topic, partition=message.partition, offset=message.offset)

def get_producer():
    return KafkaProducer(bootstrap_servers="localhost:9092")

# Export the router
__all__ = ["router"]
```

Please note that this code uses a simple `KafkaProducer` for demonstration purposes. You would need to replace the `bootstrap_servers` parameter with your actual Kafka broker URL.
